#!/usr/bin/env python3
"""Personalise one NPV Tunnel (Android) config file for a single customer.

An .npvs file is `NPVS\\x01`, a big-endian header length, a JSON header,
a 12-byte nonce, a big-endian body length, the ChaCha20-Poly1305 body
(the header bytes are its associated data), and a 64-byte ECDSA P-256
signature over everything before it.

Unlike the iPhone .npvt format, the Android one is not locked by a
policy field the app is asked to honour: the body key is sealed to the
buyer's own public key with ECDH, so a file built for one phone cannot
be decrypted on any other. That key *is* the device id the customer
sends — 44 base64url characters holding a compressed P-256 point — which
is why an id that is not a point on the curve has to be refused before
an account is created rather than after (see `validate` below, which
needs no third-party library and therefore always runs).

The admin uploads an "appKey" file — one the app itself can open — and
this rewrites the SSH username, the SSH password, the config name and
the two on-screen messages, then re-seals the result to the buyer. The
server, port, SNI and payload are carried across exactly as uploaded.

Usage:
    npvs_edit.py check <file>
        One JSON object describing the file; exit 0 if it is an NPVS
        file, 1 otherwise.

    npvs_edit.py validate <device-id>
        Exit 0 if the id is a public key this format can seal to.

    npvs_edit.py build <in> <out>
        Reads a JSON object of fields from stdin and writes the
        personalised file. Fields arrive on stdin rather than argv so
        that Arabic message text needs no shell quoting at all.
"""
import base64, hashlib, json, os, re, struct, sys, zlib

MAGIC = b"NPVS\x01"

# The app's own white-box lookup tables (zlib + base64) and the header
# skeleton of a file it accepts. Data only — nothing here is executed.
WB_BLOB = ""

INPUT_B64_TEMPLATE = ''

DEFAULT_CONFIG = {"name":"stc free","address":"172.65.90.47:443","type":"SSH","sshConfig":{"sshConfigType":"SSH-TLS-Payload","sshHost":"172.65.90.47","sshPort":443,"sshUsername":"dahoom733397","sshPassword":"@mooa322","sni":"dahoomvip.dahoomvip1.store","payload":"GET /cdn-cgi/trace HTTP/1.1[crlf]Host: 172.65.90.47[crlf][crlf]CF-RAY / HTTP/1.1[crlf]Host: dahoomvip.dahoomvip1.store[crlf]Upgrade: Websocket[crlf]Connection: Keep-Alive[crlf]User-Agent: [ua][crlf]Upgrade: websocket[crlf][crlf]"},"lockConfig":{"version":1,"isLocked":False,"password":"","onlyMobileNetwork":False,"blockRootedAndJailbroken":False,"onlyOfficialStores":False,"expiryDate":"","deviceIds":"","message":"","customServerMessage":""}}


# ── The white-box block function ──────────────────────────────────────
# Byte-for-byte the same arithmetic the app uses, driven as a CTR
# keystream. It is needed for exactly one thing: unwrapping the app key
# out of an admin's own file so its server settings can be read.
_TABLES = None


def _tables():
    global _TABLES
    if _TABLES is None:
        blob = zlib.decompress(base64.b64decode(WB_BLOB))
        x = blob[:24576]
        ty = [list(struct.unpack('>256i', blob[24576 + i * 1024:24576 + (i + 1) * 1024])) for i in range(16)]
        mb = [list(struct.unpack('>256i', blob[40960 + i * 1024:40960 + (i + 1) * 1024])) for i in range(16)]
        tb = [list(blob[57344 + i * 256:57344 + (i + 1) * 256]) for i in range(16)]
        _TABLES = (x, ty, mb, tb)
    return _TABLES


def _wb_block(st):
    x, ty, mb, tb = _tables()

    def xor(r, i, n0, n1):
        return x[(r * 96 + i) * 256 + n0 * 16 + n1]

    s = list(st)
    perm = [0, 5, 10, 15, 4, 9, 14, 3, 8, 13, 2, 7, 12, 1, 6, 11]
    for r in range(1):
        s = [s[perm[i]] for i in range(16)]
        for c in range(4):
            i4 = c * 4
            tt = [ty[r * 16 + i4 + k][s[i4 + k]] for k in range(4)]
            for b in range(4):
                i9 = c * 24 + b * 6
                s1, s2 = 28 - b * 8, 24 - b * 8
                b3 = xor(r, i9, (tt[0] >> s1) & 15, (tt[1] >> s1) & 15)
                b4 = xor(r, i9 + 1, (tt[2] >> s1) & 15, (tt[3] >> s1) & 15)
                m1 = xor(r, i9 + 2, (tt[0] >> s2) & 15, (tt[1] >> s2) & 15)
                m2 = xor(r, i9 + 3, (tt[2] >> s2) & 15, (tt[3] >> s2) & 15)
                s[i4 + b] = (xor(r, i9 + 4, b3, b4) << 4) | xor(r, i9 + 5, m1, m2)
            tt = [mb[r * 96 + i4 + k][s[i4 + k]] for k in range(4)]
            for b in range(4):
                i9 = c * 24 + b * 6
                s1, s2 = 28 - b * 8, 24 - b * 8
                m1 = xor(r, i9, (tt[0] >> s1) & 15, (tt[1] >> s1) & 15)
                m2 = xor(r, i9 + 1, (tt[2] >> s1) & 15, (tt[3] >> s1) & 15)
                m3 = xor(r, i9 + 2, (tt[0] >> s2) & 15, (tt[1] >> s2) & 15)
                m4 = xor(r, i9 + 3, (tt[2] >> s2) & 15, (tt[3] >> s2) & 15)
                s[i4 + b] = (xor(r, i9 + 4, m1, m2) << 4) | xor(r, i9 + 5, m3, m4)
    s = [s[perm[i]] for i in range(16)]
    return [tb[i][s[i]] for i in range(16)]


def _wb(data):
    ctr = bytearray(data[:16])
    ct = data[16:]
    out = bytearray()
    for i in range(0, len(ct), 16):
        ks = _wb_block(ctr)
        for j in range(15, -1, -1):
            ctr[j] = (ctr[j] + 1) & 255
            if ctr[j]:
                break
        chunk = ct[i:i + 16]
        out += bytes(chunk[k] ^ ks[k] for k in range(len(chunk)))
    return bytes(out)


# ── base64url helpers ─────────────────────────────────────────────────
def _u64(s):
    return base64.b64decode(s.replace('-', '+').replace('_', '/') + '=' * (-len(s) % 4))


def _m64u(b):
    return base64.urlsafe_b64encode(b).decode().rstrip('=')


def _denp(o):
    """Some string values arrive wrapped as "npvs1:<base64>". Unwrapping
    them here means the rest of this file only ever sees plain text."""
    if isinstance(o, dict):
        return {k: _denp(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_denp(v) for v in o]
    if isinstance(o, str) and o.startswith('npvs1:'):
        try:
            return base64.b64decode(o[6:]).decode()
        except Exception:
            return o
    return o


# ── Is this device id something we can actually seal to? ──────────────
# P-256 in full: y² = x³ - 3x + b over F_p. A compressed point carries
# only x, so the check is that an x in range has a square root here —
# which is what makes the id a real public key rather than a word the
# customer typed. Deliberately written with plain integers so it runs on
# a server where the cryptography package was never installed: an id has
# to be refused before an account is created, and a missing library must
# not turn that refusal into an acceptance.
_P = 0xffffffff00000001000000000000000000000000ffffffffffffffffffffffff
_B = 0x5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b


def is_valid_device_id(device_id):
    if not isinstance(device_id, str):
        return False
    device_id = device_id.strip()
    if len(device_id) != 44 or re.search(r'[^A-Za-z0-9_-]', device_id):
        return False
    try:
        raw = _u64(device_id)
    except Exception:
        return False
    if len(raw) != 33 or raw[0] not in (2, 3):
        return False
    x = int.from_bytes(raw[1:], 'big')
    if x >= _P:
        return False
    rhs = (x * x % _P * x - 3 * x + _B) % _P
    # Euler's criterion: rhs is a square mod p exactly when rhs^((p-1)/2)
    # is 1. (rhs == 0 never happens for a curve of prime order.)
    return pow(rhs, (_P - 1) // 2, _P) == 1


# ── Reading an admin's file ───────────────────────────────────────────
def is_npvs(raw):
    return raw[:5] == MAGIC


def read_config(raw):
    """The server settings out of an "appKey" file — one the app itself
    can open. A "recipients" file is sealed to a particular phone and
    cannot be read here at all, which is the whole point of the format."""
    if not is_npvs(raw):
        raise ValueError("not an NPVS file")
    from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305
    hs = struct.unpack('>I', raw[5:9])[0]
    hdr = json.loads(raw[9:9 + hs])
    if 'appKey' not in hdr:
        raise ValueError("recipients file: sealed to a device, not readable here")
    salt = _u64(hdr['appKey']['salt'])
    wrap = _u64(hdr['appKey']['wrap'])
    kdk = _wb(salt + b'\x00' * 16)
    master = hashlib.sha256(b"npvtunnel/appkey/v1 " + kdk).digest()
    ck = ChaCha20Poly1305(master).decrypt(wrap[:12], wrap[12:], salt)
    e = 9 + hs
    nonce = raw[e:e + 12]
    cl = struct.unpack('>I', raw[e + 12:e + 16])[0]
    body = json.loads(ChaCha20Poly1305(ck).decrypt(nonce, raw[e + 16:e + 16 + cl], raw[9:9 + hs]))
    return _denp(body['configs'][0] if 'configs' in body else body)


# ── Rewriting and re-sealing ──────────────────────────────────────────
def _next_name(current):
    """A fresh name on every build. The app lists configs by name, so a
    customer buying twice would otherwise end up with two identical rows
    and no way to tell which is which. Any trailing _<digits> the admin's
    own file carries is replaced rather than appended to, so the names
    stay the shape the admin chose instead of growing a tail."""
    stem = re.sub(r'_\d+$', '', str(current or '').strip()) or 'dahoom'
    return '%s_%d' % (stem, int.from_bytes(os.urandom(3), 'big') % 900000 + 100000)


def _apply(cfg, fields):
    ssh = cfg.get('sshConfig')
    if isinstance(ssh, dict):
        for key, value in (("sshUsername", fields.get("user")),
                           ("sshPassword", fields.get("password"))):
            if value is not None:
                ssh[key] = value
    lock = cfg.get('lockConfig')
    if isinstance(lock, dict):
        # deviceIds and isLocked are left exactly as the admin's file had
        # them. On Android the binding is the seal below — the body key
        # is encrypted to this one phone's public key — so a policy field
        # asking the app to please check an id would add nothing, and
        # switching isLocked on with no id in it could only misfire.
        for key, value in (("message", fields.get("lock_message")),
                           ("customServerMessage", fields.get("server_message"))):
            if value is not None:
                lock[key] = value
    name = fields.get("name")
    if name:
        cfg['name'] = name
    elif fields.get("randomize_name"):
        cfg['name'] = _next_name(cfg.get('name'))
    return cfg


def seal(cfg, device_id, fields=None):
    """Wraps the config for one phone: a random body key, that key
    encrypted to the buyer's public key over an ephemeral ECDH exchange,
    and the whole envelope signed by a creator key generated for this
    file alone."""
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM, ChaCha20Poly1305
    from cryptography.hazmat.primitives.kdf.hkdf import HKDF
    from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

    fields = fields or {}
    if not is_valid_device_id(device_id):
        raise ValueError("device id is not a usable public key")

    tpl = base64.b64decode(''.join(INPUT_B64_TEMPLATE.split()))
    hs0 = struct.unpack('>I', tpl[5:9])[0]
    hdr = json.loads(tpl[9:9 + hs0])

    # A new configId every time, so the app treats each delivery as its
    # own config instead of silently ignoring the second one.
    config_id = os.urandom(16)
    hdr['configId'] = _m64u(config_id)
    pol = hdr.get('policy', {})
    for key, value in (("displayMessage", fields.get("lock_message")),
                       ("customServerMessage", fields.get("server_message"))):
        if value is not None:
            pol[key] = value
    hdr['policy'] = pol

    pub_bytes = _u64(device_id)
    recipient_fp = hashlib.sha256(pub_bytes).digest()
    dek = os.urandom(32)
    recipient_pub = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), pub_bytes)
    eph_priv = ec.generate_private_key(ec.SECP256R1())
    eph_pub = eph_priv.public_key().public_bytes(Encoding.X962, PublicFormat.CompressedPoint)
    shared = eph_priv.exchange(ec.ECDH(), recipient_pub)
    aes_key = HKDF(hashes.SHA256(), 32, recipient_fp, b"NPVS-v1-wrap" + config_id).derive(shared)
    n1 = os.urandom(12)
    wrap = eph_pub + n1 + AESGCM(aes_key).encrypt(n1, dek, recipient_fp)
    hdr['recipients'] = [{'fp': _m64u(recipient_fp), 'wrap': _m64u(wrap)}]
    hdr.pop('appKey', None)

    priv = ec.generate_private_key(ec.SECP256R1())
    comp = priv.public_key().public_bytes(Encoding.X962, PublicFormat.CompressedPoint)
    hdr['creator'] = {'fp': _m64u(hashlib.sha256(comp).digest()), 'pk': _m64u(comp)}

    hb = json.dumps(hdr, separators=(',', ':')).encode()
    n2 = os.urandom(12)
    body = ChaCha20Poly1305(dek).encrypt(
        n2, json.dumps({'configs': [cfg]}, separators=(',', ':')).encode(), hb)
    env = bytearray(MAGIC)
    env += struct.pack('>I', len(hb)) + hb
    env += n2 + struct.pack('>I', len(body)) + body
    r, s = decode_dss_signature(priv.sign(bytes(env), ec.ECDSA(hashes.SHA256())))
    return bytes(env) + r.to_bytes(32, 'big') + s.to_bytes(32, 'big')


def personalise(raw, fields):
    """The admin's uploaded file in, one buyer's copy out. If the upload
    cannot be read the built-in config is used instead, exactly as the
    reference script does — the buyer still gets a working file."""
    try:
        cfg = read_config(raw)
    except Exception:
        cfg = json.loads(json.dumps(DEFAULT_CONFIG))
    _apply(cfg, fields)
    return seal(cfg, fields.get("device_id", ""), fields)


def describe(raw):
    """What the panel shows the admin right after an upload."""
    info = {"npvs": False}
    if not is_npvs(raw):
        return info
    info["npvs"] = True
    try:
        cfg = read_config(raw)
    except Exception as exc:
        info["error"] = str(exc)
        return info
    ssh = cfg.get("sshConfig") if isinstance(cfg.get("sshConfig"), dict) else {}
    lock = cfg.get("lockConfig") if isinstance(cfg.get("lockConfig"), dict) else {}
    info["name"] = cfg.get("name", "")
    info["address"] = cfg.get("address", "")
    info["has_lock"] = bool(lock)
    info["locked"] = bool(lock.get("isLocked"))
    info["editable"] = "sshUsername" in ssh
    return info


def main(argv):
    if len(argv) >= 3 and argv[1] == "check":
        raw = open(argv[2], "rb").read()
        info = describe(raw)
        print(json.dumps(info, ensure_ascii=False))
        return 0 if info.get("npvs") else 1
    if len(argv) >= 3 and argv[1] == "validate":
        return 0 if is_valid_device_id(argv[2]) else 1
    if len(argv) >= 4 and argv[1] == "build":
        fields = json.loads(sys.stdin.read() or "{}")
        out = personalise(open(argv[2], "rb").read(), fields)
        open(argv[3], "wb").write(out)
        return 0
    sys.stderr.write(__doc__)
    return 2


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except Exception as exc:            # a bad upload must not traceback
        sys.stderr.write("npvs_edit: %s\n" % exc)
        sys.exit(1)
